1  import React, {useCallback, useContext, useMemo, useState} from 'react';
     2  import type {ReportActionListItemType, ReportListItemType, TransactionListItemType} from '@components/SelectionList/types';
     3  import * as SearchUIUtils from '@libs/SearchUIUtils';
     4  import type ChildrenProps from '@src/types/utils/ChildrenProps';
     5  import type {SearchContext, SelectedTransactions} from './types';
     6
     7  const defaultSearchContext = {
     8      currentSearchHash: -1,
     9      selectedTransactions: {},
    10      selectedReports: [],
    11      setCurrentSearchHash: () => {},
    12      setSelectedTransactions: () => {},
    13      clearSelectedTransactions: () => {},
    14      shouldShowStatusBarLoading: false,
    15      setShouldShowStatusBarLoading: () => {},
    16      lastSearchType: undefined,
    17      setLastSearchType: () => {},
    18  };
    19
    20  const Context = React.createContext<SearchContext>(defaultSearchContext);
    21
    22  function getReportsFromSelectedTransactions(data: TransactionListItemType[] | ReportListItemType[] | ReportActionListItemType[], selectedTransactions: SelectedTransactions) {
    23      return (data ?? [])
    24          .filter(
    25              (item) =>
    26                  !SearchUIUtils.isTransactionListItemType(item) &&
    27                  !SearchUIUtils.isReportActionListItemType(item) &&
    28                  item.reportID &&
    29                  item?.transactions?.every((transaction: {keyForList: string | number}) => selectedTransactions[transaction.keyForList]?.isSelected),
    30          )
    31          .map((item) => item.reportID);
    32  }
    33
    34  function SearchContextProvider({children}: ChildrenProps) {
    35      const [searchContextData, setSearchContextData] = useState<Pick<SearchContext, 'currentSearchHash' | 'selectedTransactions' | 'selectedReports'>>({
    36          currentSearchHash: defaultSearchContext.currentSearchHash,
    37          selectedTransactions: defaultSearchContext.selectedTransactions,
    38          selectedReports: defaultSearchContext.selectedReports,
    39      });
    40
    41      const setCurrentSearchHash = useCallback((searchHash: number) => {
    42          setSearchContextData((prevState) => ({
    43              ...prevState,
    44              currentSearchHash: searchHash,
    45          }));
    46      }, []);
    47
    48      const setSelectedTransactions = useCallback((selectedTransactions: SelectedTransactions, data: TransactionListItemType[] | ReportListItemType[] | ReportActionListItemType[]) => {
    49          // When selecting transactions, we also need to manage the reports to which these transactions belong. This is done to ensure proper exporting to CSV.
    50          const selectedReports = getReportsFromSelectedTransactions(data, selectedTransactions);
    51
    52          setSearchContextData((prevState) => ({
    53              ...prevState,
    54              selectedTransactions,
    55              selectedReports,
    56          }));
    57      }, []);
    58
    59      const clearSelectedTransactions = useCallback(
    60          (searchHash?: number) => {
    61              if (searchHash === searchContextData.currentSearchHash) {
    62                  return;
    63              }
    64              setSearchContextData((prevState) => ({
    65                  ...prevState,
    66                  selectedTransactions: {},
    67                  selectedReports: [],
    68              }));
    69          },
    70          [searchContextData.currentSearchHash],
    71      );
    72
    73      const [shouldShowStatusBarLoading, setShouldShowStatusBarLoading] = useState(false);
    74      const [lastSearchType, setLastSearchType] = useState<string | undefined>(undefined);
    75
    76      const searchContext = useMemo<SearchContext>(
    77          () => ({
    78              ...searchContextData,
    79              setCurrentSearchHash,
    80              setSelectedTransactions,
    81              clearSelectedTransactions,
    82              shouldShowStatusBarLoading,
    83              setShouldShowStatusBarLoading,
    84              lastSearchType,
    85              setLastSearchType,
    86          }),
    87          [searchContextData, setCurrentSearchHash, setSelectedTransactions, clearSelectedTransactions, shouldShowStatusBarLoading, lastSearchType, setLastSearchType],
    88      );
    89
    90      return <Context.Provider value={searchContext}>{children}</Context.Provider>;
    91  }
    92
    93  function useSearchContext() {
    94      return useContext(Context);
    95  }
    96
    97  SearchContextProvider.displayName = 'SearchContextProvider';
    98
    99  export {SearchContextProvider, useSearchContext};

